const listRecoverableOrgSignupCompletions = `-- name: ListRecoverableOrgSignupCompletions :many
SELECT
    operation_id,
    org_signup_request_id,
    token_hash,
    idempotency_key,
    request_digest,
    org_did,
    domain,
    reserve_command_id,
    activate_command_id,
    payload_ciphertext,
    state,
    failure_reason,
    provisioning_expires_at,
    attempt_count,
    next_attempt_at,
    last_error,
    created_at,
    updated_at,
    completed_at,
    expires_at
FROM vetchium.org_signup_completions
WHERE state NOT IN ('completed', 'failed')
  AND next_attempt_at <= now()
ORDER BY next_attempt_at, created_at
LIMIT 25
`

func (q *Queries) ListRecoverableOrgSignupCompletions(ctx context.Context) ([]VetchiumOrgSignupCompletion, error) {
	rows, err := q.db.Query(ctx, listRecoverableOrgSignupCompletions)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []VetchiumOrgSignupCompletion
	for rows.Next() {
		var i VetchiumOrgSignupCompletion
		if err := rows.Scan(
			&i.OperationID,
			&i.OrgSignupRequestID,
			&i.TokenHash,
			&i.IdempotencyKey,
			&i.RequestDigest,
			&i.OrgDid,
			&i.Domain,
			&i.ReserveCommandID,
			&i.ActivateCommandID,
			&i.PayloadCiphertext,
			&i.State,
			&i.FailureReason,
			&i.ProvisioningExpiresAt,
			&i.AttemptCount,
			&i.NextAttemptAt,
			&i.LastError,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.CompletedAt,
			&i.ExpiresAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

