const prepareOrgSignupCompletion = `-- name: PrepareOrgSignupCompletion :one
WITH eligible_signup AS (
    SELECT s.org_signup_request_id, s.domain
    FROM vetchium.org_signup_requests AS s
    WHERE s.org_signup_request_id = $1
      AND s.token_hash = $2
      AND s.active
      AND s.consumed_at IS NULL
      AND s.expires_at > now()
      AND NOT EXISTS (
          SELECT 1 FROM vetchium.org_signup_blocked_domains AS b
          WHERE s.domain = b.domain OR s.domain LIKE '%.' || b.domain
      )
      AND NOT EXISTS (
          SELECT 1 FROM vetchium.org_domains AS d
          WHERE d.domain = s.domain AND d.domain_state <> 'released'
      )
    FOR UPDATE
), inserted AS (
    INSERT INTO vetchium.org_signup_completions (
        operation_id,
        org_signup_request_id,
        token_hash,
        idempotency_key,
        request_digest,
        org_did,
        domain,
        reserve_command_id,
        activate_command_id,
        payload_ciphertext,
        provisioning_expires_at,
        expires_at
    )
    SELECT
        $3,
        org_signup_request_id,
        $2,
        $4,
        $5,
        $6,
        domain,
        $7,
        $8,
        $9,
        $10,
        $11
    FROM eligible_signup
    ON CONFLICT DO NOTHING
    RETURNING operation_id, org_signup_request_id, token_hash, idempotency_key, request_digest, org_did, domain, reserve_command_id, activate_command_id, payload_ciphertext, state, failure_reason, provisioning_expires_at, attempt_count, next_attempt_at, last_error, created_at, updated_at, completed_at, expires_at
), audit AS (
    INSERT INTO vetchium.audit_events (
        tenant_id, action, entity_type, entity_id, actor_type, source,
        idempotency_key, payload
    )
    SELECT
        $12,
        'org.signup.completion_prepared',
        'org_signup_completion',
        operation_id::text,
        'anonymous',
        'orgs-api',
        $4,
        jsonb_build_object('org_did', org_did, 'domain', domain)
    FROM inserted
)
SELECT
    operation_id,
    org_signup_request_id,
    token_hash,
    idempotency_key,
    request_digest,
    org_did,
    domain,
    reserve_command_id,
    activate_command_id,
    payload_ciphertext,
    state,
    failure_reason,
    provisioning_expires_at,
    attempt_count,
    next_attempt_at,
    last_error,
    created_at,
    updated_at,
    completed_at,
    expires_at
FROM inserted
`

